'use strict';

import axios from "axios";
import defaults from "axios/lib/defaults";

/**
 *
 * @export
 * @class CommunicationService
 */
export class CommunicationService extends axios.Axios {

    constructor(){
        super(defaults);

        let self = this;
        let last_config = null;

        /**
         * Add a request interceptor
         * check the token before request is sent
         */
        this.interceptors.request.use(async function (config) {
            if (config.url != 'v1/oauth/refreshToken' && config.url != 'v1/oauth2/token' && config.url != config.baseURL ) {
                //Save the request
                self.last_config = Object.assign({}, config);

                if (!self.checkToken()){
                    let lapsed_time = ((new Date().getTime()) - self.expirationTime)/ 1000;
                    
                    //If the token is expired, got to refresh
                    if (self.token && lapsed_time > 3600){

                        await self.refreshToken()
                            .then(res => {
                                self.last_config.headers['Authorization'] = 'Bearer ' + self.token;
                                self.last_config.headers['X-Real-origin'] = 'cor-auth-service';
                                return self.last_config;
                            })
                            .catch(async (err) => {
                                //Generate token
                                await self.generateToken()
                                    .then(res => {
                                        self.initiateHeaderAuth(self.token);
                                        self.last_config.headers['Authorization'] = 'Bearer ' + self.token;
                                        self.last_config.headers['X-Real-origin'] = 'cor-auth-service';
                                        return self.last_config;
                                    })
                                    .catch(err => {
                                        return Promise.reject(err);
                                    })
                            })

                    }else {
                    
                        //Generate token
                        await self.generateToken()
                            .then(res => {
                                self.initiateHeaderAuth(self.token);
                                self.last_config.headers['Authorization'] = 'Bearer ' + self.token;
                                self.last_config.headers['X-Real-origin'] = 'cor-auth-service';
                                return self.last_config;
                            })
                            .catch(err => {
                                return Promise.reject(err);
                            })
                    }
                }else{
                    config.headers['Authorization'] = 'Bearer ' + self.token;
                    config.headers['X-Real-origin'] = 'cor-auth-service';
                }
            }
            
            return config;

        }, function (err) {
            // Do something with request error
            return Promise.reject(err);
        });



        /**
         * Add a response interceptor
         */
        this.interceptors.response.use(function (response) {
            // Do something with response data
            
            //Return only the data
            response = response.data ? response.data : response;

            return response;
        }, async function (err) {
               
            if (err && err.response && err.response.config && err.response.config.url != 'v1/oauth/refreshToken' && err.response.config.url != 'v1/oauth2/token' ) {
                //Save the request
                self.last_config = Object.assign({}, err.response.config);

                // Do something with response error
                if (err.response.data.code == "AT005") {

                    return new Promise((resolve, reject)=>{
                        self.refreshToken()
                        .then(async (res) => {
                            self.last_config.headers['Authorization'] = 'Bearer ' + self.token;
                            self.initiateHeaderAuth(self.token);
                            let result = await self.request(self.last_config);
                            resolve(result);
                        })
                        .catch(async (err) => {
                            //Generate token
                            await self.generateToken()
                                .then(async(res) => {
                                    self.last_config.headers['Authorization'] = 'Bearer ' + self.token;
                                    self.initiateHeaderAuth(self.token);
                                    let result = await self.request(self.last_config);
                                    resolve(result);
                                })
                                .catch(err => {
                                    reject(err);
                                })
                        })
                    });

                }else if(err.response.data.code == "AT004" || err.response.data.code == "AT006"){

                    return new Promise((resolve, reject)=> {
                        self.generateToken()
                            .then(async(res) => {
                                self.last_config.headers['Authorization'] = 'Bearer ' + self.token;
                                self.initiateHeaderAuth(self.token);
                                let result = await self.request(self.last_config);
                                resolve(result);
                            })
                            .catch(err => {
                                reject(err);
                            })
                    });
                }else{
                    return Promise.reject(err.response);
                }
            }else{
                
                return (err.response)? Promise.reject(err.response) : Promise.reject(err);
            }
        });
    }

    initiateBaseURL(){
        this.defaults.baseURL = this.environment.apiEndpoint;
    }

    initiateHeaderAuth(token){
        this.defaults.headers['Authorization'] = 'Bearer ' + token;
        this.defaults.headers['X-Real-origin'] = 'cor-auth-service';
    }

    
}